const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
const percent = new Intl.NumberFormat("en-US", { style: "percent" });

console.log(compact.format(999_999));
console.log(compact.format(1500));
console.log(percent.format(0.075));
console.log(new Intl.ListFormat("en-US").format(["red", "green"]));
console.log(new Intl.PluralRules("en-US", { type: "ordinal" }).select(13));
